package io.doindev.codegraph.dba;

import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.junit.jupiter.api.io.TempDir;
import java.nio.file.Path;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="DBA_COMPARE_DISPOSABLE",matches="cgraph-compare-qa-[a-f0-9]+")
class PostgresTransitionsVendorTest {
    @TempDir Path directory;
    @Test @Timeout(180) void viewRebuildEnumDomainPoliciesAndGrantsRoundTrip()throws Exception{
        Assumptions.assumeTrue(System.getenv("DBA_COMPARE_VENDOR").equals("postgresql"));
        try(var profiles=new Profiles(directory,new DbaTest.MemoryVault());var connections=new Connections(profiles);var jobs=new QueryJobs(connections,new DbaConfig(directory,384L<<20,2,100,100,120),s->true);var compare=new DatabaseCompare(profiles,connections,jobs,directory,s->true)){
            String source=profiles.put(null,CompareVendorIntegrationTest.profile("postgresql","Transitions source",System.getenv("DBA_COMPARE_SOURCE"))).path("id").asText(),dest=profiles.put(null,CompareVendorIntegrationTest.profile("postgresql","Transitions destination",System.getenv("DBA_COMPARE_DESTINATION"))).path("id").asText();
            try(var a=connections.open(source);var b=connections.open(dest);var left=a.createStatement();var right=b.createStatement()){
                a.setAutoCommit(true);b.setAutoCommit(true);for(var st:java.util.List.of(left,right)){st.execute("CREATE SCHEMA transitions");st.execute("CREATE TYPE transitions.state AS ENUM ('open')");st.execute("CREATE DOMAIN transitions.amount AS numeric(20,4) DEFAULT 1 CONSTRAINT positive CHECK (VALUE>=0)");st.execute("CREATE TABLE transitions.t(id int PRIMARY KEY, title text, state transitions.state DEFAULT 'open', amount transitions.amount)");st.execute("CREATE VIEW transitions.v AS SELECT id,title FROM transitions.t");st.execute("CREATE VIEW transitions.nested AS SELECT id,title FROM transitions.v");st.execute("CREATE MATERIALIZED VIEW transitions.mv AS SELECT id,title FROM transitions.nested WITH NO DATA");}
                left.execute("ALTER TYPE transitions.state ADD VALUE 'closed'");left.execute("ALTER DOMAIN transitions.amount SET DEFAULT 2");left.execute("ALTER DOMAIN transitions.amount DROP CONSTRAINT positive");left.execute("ALTER DOMAIN transitions.amount ADD CONSTRAINT positive CHECK (VALUE>=1)");left.execute("CREATE OR REPLACE VIEW transitions.v AS SELECT id,title,amount FROM transitions.t");left.execute("CREATE OR REPLACE VIEW transitions.nested AS SELECT id,title,amount FROM transitions.v");left.execute("DROP MATERIALIZED VIEW transitions.mv");left.execute("CREATE MATERIALIZED VIEW transitions.mv AS SELECT id,title,amount FROM transitions.nested WITH NO DATA");left.execute("COMMENT ON MATERIALIZED VIEW transitions.mv IS 'retained native metadata'");left.execute("GRANT SELECT ON transitions.mv TO PUBLIC");left.execute("ALTER TABLE transitions.t ENABLE ROW LEVEL SECURITY");left.execute("CREATE POLICY visible ON transitions.t USING (id>0)");
                for(var st:java.util.List.of(left,right)){st.execute("CREATE ROLE transition_reader");st.execute("CREATE TABLE transitions.identity_storage(id bigint GENERATED BY DEFAULT AS IDENTITY, payload text)");st.execute("CREATE FUNCTION transitions.answer() RETURNS integer LANGUAGE sql AS 'SELECT 42'");}
                left.execute("ALTER TABLE transitions.identity_storage ALTER COLUMN id SET GENERATED ALWAYS");left.execute("ALTER TABLE transitions.identity_storage SET UNLOGGED");left.execute("ALTER TABLE transitions.identity_storage SET (fillfactor=75)");left.execute("ALTER SEQUENCE transitions.identity_storage_id_seq CACHE 7");left.execute("DROP FUNCTION transitions.answer()");left.execute("CREATE FUNCTION transitions.answer() RETURNS bigint LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog AS 'SELECT 42::bigint'");left.execute("COMMENT ON FUNCTION transitions.answer() IS 'routine comment'");left.execute("GRANT EXECUTE ON FUNCTION transitions.answer() TO transition_reader");
                left.execute("REVOKE USAGE ON TYPE transitions.state FROM PUBLIC");left.execute("GRANT USAGE ON TYPE transitions.state TO transition_reader");left.execute("COMMENT ON DOMAIN transitions.amount IS 'domain metadata'");left.execute("GRANT SELECT(title) ON transitions.v TO transition_reader WITH GRANT OPTION");left.execute("REVOKE EXECUTE ON FUNCTION transitions.answer() FROM PUBLIC");
                left.execute("CREATE FUNCTION transitions.audit_row() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RETURN NEW; END $$");left.execute("CREATE TRIGGER audit_row BEFORE INSERT ON transitions.identity_storage FOR EACH ROW EXECUTE FUNCTION transitions.audit_row()");left.execute("ALTER TABLE transitions.identity_storage DISABLE TRIGGER audit_row");left.execute("CREATE RULE no_delete AS ON DELETE TO transitions.identity_storage DO INSTEAD NOTHING");
                left.execute("CREATE INDEX mv_id ON transitions.mv(id)");left.execute("COMMENT ON COLUMN transitions.mv.title IS 'column comment'");
                right.execute("ALTER DEFAULT PRIVILEGES IN SCHEMA transitions GRANT SELECT ON TABLES TO transition_reader");
                left.execute("CREATE TABLE transitions.partition_parent(id int,payload text) PARTITION BY RANGE(id)");left.execute("CREATE TABLE transitions.partition_first PARTITION OF transitions.partition_parent FOR VALUES FROM (0) TO (100)");
                var input=Profiles.JSON.createObjectNode().put("sourceReceipt",DatabaseCompareTest.receipt(compare,jobs,source,"transitions")).put("destinationReceipt",DatabaseCompareTest.receipt(compare,jobs,dest,"transitions")).put("dataMode","none");input.putArray("objectTypes").add("tables").add("views").add("materialized_views").add("types").add("functions").add("indexes");
                String id=DatabaseCompareTest.finish(jobs,compare.start("human",input)).path("comparisonId").asText();var selected=DatabaseCompareTest.select(compare,id).put("destructiveSchema",true).put("dataMode","none");var artifact=DatabaseCompareTest.finish(jobs,compare.generate("human",id,selected));String sql=compare.artifacts.preview("human",artifact.path("artifactId").asText()).path("sql").asText();assertTrue(sql.contains("DROP MATERIALIZED VIEW"));assertTrue(sql.contains("CREATE POLICY"));assertTrue(sql.indexOf("ADD VALUE")<sql.indexOf("CREATE POLICY"));right.execute(sql);compare.remove("human",id);
                id=DatabaseCompareTest.finish(jobs,compare.start("human",input)).path("comparisonId").asText();var result=compare.results("human",id,0,200,"","");for(var object:result.path("objects"))if(object.path("supported").asBoolean())assertEquals("identical",object.path("status").asText(),object.toPrettyString());compare.remove("human",id);
                try(var rows=right.executeQuery("SELECT has_table_privilege('public','transitions.mv','SELECT')")){assertTrue(rows.next());assertTrue(rows.getBoolean(1));}System.out.println("POSTGRES_TRANSITIONS_VERIFIED");
            }
        }
    }
}
